import { createServer } from 'node:http';
import { createHash } from 'node:crypto';
import { writeFile } from 'node:fs/promises';
import { build } from 'esbuild';
import { chromium, webkit } from 'playwright';
const root = process.cwd();
const adapter = (await build({ stdin: { contents: `import {createWebPlatformAdapter} from './src/platform/adapters/web/WebPlatformAdapter.ts';window.probeAdapter=createWebPlatformAdapter();window.probeEvents=[];probeAdapter.subscribe(()=>probeEvents.push({event:'adapter',snapshot:probeAdapter.getSnapshot()}));for(const type of ['online','offline'])window.addEventListener(type,()=>probeEvents.push({event:type,online:navigator.onLine}));navigator.serviceWorker.addEventListener('message',e=>probeEvents.push(e.data));navigator.serviceWorker.register('/planet/sw.js',{scope:'/planet/'});`, resolveDir: root }, bundle: true, format: 'iife', write: false })).outputFiles[0].text;
const resources = new Map([['/planet/adapter.js', adapter], ...['ru','en'].map(lang => ['/planet/'+lang+'/',`<!doctype html><html lang="${lang}"><meta charset="UTF-8"><title>Engine transport boundary only</title><h1>${lang}</h1><script src="/planet/adapter.js"></script></html>`])]);
const config = {schemaVersion:1,scopePath:'/planet/',buildId:'e'.repeat(64),entrypoints:{ru:'/planet/ru/',en:'/planet/en/'},files:[...resources].map(([url,content])=>({url,bytes:Buffer.byteLength(content),sha256:createHash('sha256').update(content).digest('hex'),kind:url.endsWith('/')?'shell':'asset'}))};
const actualWorker = (await build({stdin:{contents:`import {installPwaWorker} from './src/pwa/serviceWorkerRuntime.js';installPwaWorker(self,${JSON.stringify(config)});`,resolveDir:root},bundle:true,format:'iife',write:false})).outputFiles[0].text;
const tinyWorker = `self.addEventListener('install',e=>e.waitUntil(caches.open('tiny').then(c=>c.addAll(${JSON.stringify([...resources.keys()])}))));self.addEventListener('activate',e=>e.waitUntil(clients.claim()));self.addEventListener('fetch',e=>{let u=new URL(e.request.url);if(${JSON.stringify([...resources.keys()])}.includes(u.pathname))e.respondWith(caches.open('tiny').then(c=>c.match(u.pathname)));});`;
const report={capturedAt:new Date().toISOString(),kind:'isolated-engine-transport-reproduction',productArtifactUnchanged:true,limits:['Tiny HTML, actual source WebPlatformAdapter, minimal or actual worker runtime; no product globe/license or full artifact pass implied.','Source modules bundled only in memory; no product source or dist mutation.'],scenarios:[]};
for(const [engineType,launch] of [[chromium,{channel:'chrome'}],[webkit,{}]]) for(const workerKind of ['minimal','actual-runtime']) {
  const requests=[];
  const server=createServer((req,res)=>{const pathname=new URL(req.url,'http://127.0.0.1').pathname;requests.push(pathname);const content=pathname==='/planet/sw.js'?(workerKind==='minimal'?tinyWorker:actualWorker):resources.get(pathname)??'network-only';res.writeHead(200,{'Content-Type':pathname.endsWith('.js')?'application/javascript; charset=utf-8':pathname.endsWith('/')?'text/html; charset=utf-8':'text/plain','Cache-Control':pathname==='/planet/sw.js'?'no-cache':'public,max-age=0'});res.end(content);});
  await new Promise(resolve=>server.listen(0,'127.0.0.1',resolve));
  const origin='http://127.0.0.1:'+server.address().port;
  const browser=await engineType.launch(launch),context=await browser.newContext({serviceWorkers:'allow'}),page=await context.newPage();
  const scenario={engine:engineType.name(),version:browser.version(),workerKind,measurements:[],requests,failures:[]};report.scenarios.push(scenario);
  page.on('requestfailed',request=>scenario.failures.push({url:request.url(),failure:request.failure()}));
  const measure=async label=>scenario.measurements.push({label,...await page.evaluate(()=>({url:location.href,online:navigator.onLine,adapter:window.probeAdapter?.getSnapshot(),events:window.probeEvents,controller:navigator.serviceWorker.controller?.scriptURL,language:document.documentElement.lang}))});
  try {
    await page.goto(origin+'/planet/ru/?country=russia#atlas');
    await page.waitForFunction(()=>navigator.serviceWorker.controller!==null);
    await measure('online-controlled');
    await context.setOffline(true);await measure('after-setOffline-before-navigation');
    try {await page.goto(origin+'/planet/en/?country=russia#atlas',{timeout:8000});}catch(error){scenario.navigationError=error.message;}
    await measure('after-offline-navigation');
    scenario.uncachedNetworkFetch=await page.evaluate(async()=>{try{const r=await fetch('/outside-network-probe',{cache:'no-store'});return {status:r.status,body:await r.text()};}catch(error){return {failed:true,error:error.message};}});
    if(engineType===chromium){
      const cdp=await context.newCDPSession(page);
      try{await cdp.send('Network.overrideNetworkState',{offline:true,latency:0,downloadThroughput:-1,uploadThroughput:-1});await page.reload({timeout:8000});await measure('explicit-CDP-override-after-reload');}catch(error){scenario.overrideError=error.message;}
      await cdp.detach();
    }
  }catch(error){scenario.error=error.message;}
  finally{await browser.close();await new Promise(resolve=>server.close(resolve));}
}
await writeFile('.tmp/worker-review/cross-engine-transport-correct-headers.json',JSON.stringify(report,null,2)+'\n');
console.log(JSON.stringify(report,null,2));
